"use client";

import { useEffect, useState } from "react";
import { Check, Star } from "lucide-react";

export default function PackagesPage() {
  const [packages, setPackages] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/packages")
      .then(res => res.json())
      .then(data => {
        setPackages(data.packages || []);
        setLoading(false);
      })
      .catch(() => {
        setPackages([]);
        setLoading(false);
      });
  }, []);

  if (loading) return <p className="p-8">Loading...</p>;

  return (
    <div className="p-8 min-h-screen">
      <h1 className="text-3xl text-gray-900 font-bold mb-2">Pricing</h1>
      <p className="text-gray-600 mb-8">
        Choose the plan that fits your team's needs.
      </p>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
        {packages.map((pkg) => (
          <div
            key={pkg.id}
            className={`relative bg-white rounded-2xl p-8 shadow-lg border border-gray-200 hover:shadow-xl transition-all duration-300 ${
              pkg.isPopular ? "border-blue-500 shadow-2xl scale-[1.02]" : ""
            }`}
          >
            {/* Popular Badge */}
            {pkg.isPopular && (
              <div className="absolute top-4 right-4 bg-blue-600 text-white px-3 py-1 text-xs rounded-full flex items-center gap-1">
                <Star size={14} />
                Popular
              </div>
            )}

            {/* Title */}
            <h2 className="text-2xl text-gray-900 font-semibold">{pkg.name}</h2>
            <p className="text-gray-500 text-sm mt-1">{pkg.description}</p>

            {/* Price */}
            <div className="mt-4 flex items-end gap-2">
              <span className="text-4xl font-bold text-gray-900">
                ₹{pkg.price}
              </span>
              <span className="text-gray-500 mb-1">/ month</span>
            </div>

            <div className="w-full h-px bg-gray-200 my-4"></div>

            {/* Features */}
            <ul className="space-y-3 text-gray-700 text-sm">
              {pkg.features.map((feature: string, idx: number) => (
                <li key={idx} className="flex items-center gap-3">
                  <Check size={18} className="text-green-600" />
                  <span>{feature}</span>
                </li>
              ))}
            </ul>

            {/* CTA Button */}
            <button
              className="mt-8 w-full bg-blue-600 text-white py-3 rounded-xl font-semibold hover:bg-blue-700 transition"
            >
              Choose {pkg.name}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}